import { createServer } from 'node:http';
import { router } from './router.js';

// HTTP entry point / 服务入口
createServer(router).listen(3000, '127.0.0.1');

import { listNotes, addNote } from './store.js';

export async function router(req, res) {
  res.setHeader('Content-Type', 'application/json');
  if (req.method === 'GET' && req.url === '/notes') {
    return res.end(JSON.stringify(listNotes()));
  }
  if (req.method === 'POST' && req.url === '/notes') {
    let body = '';
    for await (const part of req) body += part;
    try {
      const { title } = JSON.parse(body);
      if (typeof title !== 'string' || !title.trim()) throw Error('title required');
      res.statusCode = 201;
      return res.end(JSON.stringify(addNote(title)));
    } catch { res.statusCode = 400; return res.end(JSON.stringify({ error: 'Invalid title' })); }
  }
  res.statusCode = 404;
  res.end(JSON.stringify({ error: 'Not found' }));
}

import { randomUUID } from 'node:crypto';
const notes = [];
export const listNotes = () => [...notes];
export function addNote(title) {
  const note = { id: randomUUID(), title };
  notes.push(note);
  return note;
}
